sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    //Type appropriate comment here, and begin script below
    // alert(g_form.getSectionNames());



    var Approval_type = g_form.getValue('type_of_approval');
    if (Approval_type == 1) {
        g_form.setSectionDisplay('new_ideaparallelapproval', false);
        g_form.setSectionDisplay('new_ideasequentialapproval', true);
        g_form.setVisible('number_of_approvals', true);
        var no = g_form.getValue('number_of_approvals');
        if (no == 1) {
            g_form.setVisible("approval_1", true);
            g_form.setVisible("approval_2", false);
            g_form.setVisible("approval_3", false);
            g_form.setVisible("approval_4", false);
            g_form.setVisible("approval_5", false);
            g_form.setVisible("approval_6", false);
        } else if (no == 2) {
            g_form.setVisible("approval_1", true);
            g_form.setVisible("approval_2", true);
            g_form.setVisible("approval_3", false);
            g_form.setVisible("approval_4", false);
            g_form.setVisible("approval_5", false);
            g_form.setVisible("approval_6", false);
        } else if (no == 3) {
            g_form.setVisible("approval_1", true);
            g_form.setVisible("approval_2", true);
            g_form.setVisible("approval_3", true);
            g_form.setVisible("approval_4", false);
            g_form.setVisible("approval_5", false);
            g_form.setVisible("approval_6", false);
        } else if (no == 4) {
            g_form.setVisible("approval_1", true);
            g_form.setVisible("approval_2", true);
            g_form.setVisible("approval_3", true);
            g_form.setVisible("approval_4", true);
            g_form.setVisible("approval_5", false);
            g_form.setVisible("approval_6", false);

        } else if (no == 5) {
            g_form.setVisible("approval_1", true);
            g_form.setVisible("approval_2", true);
            g_form.setVisible("approval_3", true);
            g_form.setVisible("approval_4", true);
            g_form.setVisible("approval_5", true);
            g_form.setVisible("approval_6", false);

        } else {
            g_form.setVisible("approval_1", true);
            g_form.setVisible("approval_2", true);
            g_form.setVisible("approval_3", true);
            g_form.setVisible("approval_4", true);
            g_form.setVisible("approval_5", true);
            g_form.setVisible("approval_6", true);
        }

    } else if (Approval_type == 2) {
        g_form.setSectionDisplay('new_ideasequentialapproval', false);
        g_form.setSectionDisplay('new_ideaparallelapproval', true);

    }

}
